#include "common.h"
#include "webui.h"

/* The WebUI page and the tile logo are embedded as raw bytes.
 *
 * logo.png is generated by tools/make_assets.py.
 *
 * The real page is built from the webui/ React project
 * ("npm run build:embed" there) and arrives as webui.html — a single
 * self-contained HTML file — which we embed verbatim. The test build
 * keeps a tiny stub page, since it refuses installs anyway. */

/* the /logo.png handler is served in every build, including TEST_ONLY */
__asm__(
".section .rodata\n"
".global sender_logo\n"
".global sender_logo_end\n"
".global sender_logo_size\n"
".align 16\n"
"sender_logo:\n"
".incbin \"logo.png\"\n"
"sender_logo_end:\n"
"sender_logo_size:\n"
".quad sender_logo_end - sender_logo\n"
".previous\n");
extern const unsigned char sender_logo[];
extern const size_t sender_logo_size;

#ifdef TEST_ONLY
const char UI_HTML[] =
"<!DOCTYPE html><html><head><meta charset=utf-8>"
"<title>PKG Sender (test build)</title></head>"
"<body style='background:#101418;color:#eee;font-family:sans-serif;"
"display:flex;align-items:center;justify-content:center;min-height:100vh'>"
"<h2>PKG Sender receiver — TEST BUILD, installs disabled</h2>"
"</body></html>";
const size_t UI_HTML_SIZE = sizeof(UI_HTML) - 1;
#else
__asm__(
".section .rodata\n"
".global UI_HTML\n"
".global UI_HTML_end\n"
".global UI_HTML_SIZE\n"
".align 16\n"
"UI_HTML:\n"
".incbin \"webui.html\"\n"
"UI_HTML_end:\n"
"UI_HTML_SIZE:\n"
".quad UI_HTML_end - UI_HTML\n"
".previous\n");
extern const char UI_HTML[];
extern const size_t UI_HTML_SIZE;
#endif /* TEST_ONLY */
